import{_ as o,o as a,c as e,a2 as r}from"./chunks/framework.A5mep7Fe.js";const A=JSON.parse('{"title":"🎭 02 · GAN 与 VAE（生成式基石）","description":"","frontmatter":{},"headers":[],"relativePath":"02-算法岗-AIGC生成式/02-GAN与VAE.md","filePath":"02-算法岗-AIGC生成式/02-GAN与VAE.md","lastUpdated":1786806808000}'),d={name:"02-算法岗-AIGC生成式/02-GAN与VAE.md"};function n(l,t,s,i,p,h){return a(),e("div",null,[...t[0]||(t[0]=[r('<h1 id="🎭-02-·-gan-与-vae-生成式基石" tabindex="-1">🎭 02 · GAN 与 VAE（生成式基石） <a class="header-anchor" href="#🎭-02-·-gan-与-vae-生成式基石" aria-label="Permalink to &quot;🎭 02 · GAN 与 VAE（生成式基石）&quot;">​</a></h1><blockquote><p>虽被 Diffusion 抢了风头，GAN/VAE 仍是理解生成模型的基石，且在高保真/表征学习上仍有价值。</p></blockquote><hr><h2 id="一、gan-生成对抗网络" tabindex="-1">一、GAN（生成对抗网络） <a class="header-anchor" href="#一、gan-生成对抗网络" aria-label="Permalink to &quot;一、GAN（生成对抗网络）&quot;">​</a></h2><p><strong>思想</strong>：两个网络博弈——</p><ul><li><strong>生成器 G</strong>：把随机噪声 $z$ 映射为「假样本」</li><li><strong>判别器 D</strong>：区分真样本 vs G 生成的假样本</li></ul><p><strong>极小极大博弈</strong>：</p><p>$$\\min_G \\max_D \\mathbb{E}<em>{x\\sim p</em>{data}}[\\log D(x)] + \\mathbb{E}_z[\\log(1 - D(G(z)))]$$</p><p>训练动态：G 越逼真假样本，D 越难分辨，直到纳什均衡（D 输出 0.5）。</p><p><strong>代表</strong>：DCGAN、StyleGAN（高保真人脸）、BigGAN（大类生成）、CycleGAN（无配对图像翻译）。</p><p><strong>优缺点</strong>：</p><ul><li>✅ 生成速度快（一次前向）、高保真</li><li>❌ 训练不稳定、易模式崩塌（mode collapse）、难评估</li></ul><hr><h2 id="二、vae-变分自编码器" tabindex="-1">二、VAE（变分自编码器） <a class="header-anchor" href="#二、vae-变分自编码器" aria-label="Permalink to &quot;二、VAE（变分自编码器）&quot;">​</a></h2><p><strong>思想</strong>：学一个<strong>隐变量分布</strong> $q(z|x)$，编码器映射 $x\\to$ 分布参数，解码器从 $z$ 重建 $x$。</p><p><strong>优化目标 = 重构损失 + KL 散度（ELBO）</strong>：</p><p>$$\\mathcal{L} = \\mathbb{E}_{q(z|x)}[\\log p(x|z)] - \\text{KL}(q(z|x),|,p(z))$$</p><ul><li>KL 项约束隐空间接近标准正态（保证可采样生成）</li><li>重构项保证重建质量</li></ul><p><strong>VQ-VAE / VQGAN</strong>：把连续 latent 离散化为 codebook，是很多文生图/视频的 tokenizer 基础。</p><hr><h2 id="三、三大生成范式对比-面试必会" tabindex="-1">三、三大生成范式对比（面试必会） <a class="header-anchor" href="#三、三大生成范式对比-面试必会" aria-label="Permalink to &quot;三、三大生成范式对比（面试必会）&quot;">​</a></h2><table tabindex="0"><thead><tr><th>维度</th><th>GAN</th><th>VAE</th><th>Diffusion</th></tr></thead><tbody><tr><td>训练稳定性</td><td>差</td><td>好</td><td>好</td></tr><tr><td>生成速度</td><td>快（1步）</td><td>快</td><td>慢（多步，可加速）</td></tr><tr><td>样本质量</td><td>高（但易崩）</td><td>中（偏模糊）</td><td>高</td></tr><tr><td>模式覆盖</td><td>易 collapse</td><td>好</td><td>好</td></tr><tr><td>可微可控性</td><td>中</td><td>好（有隐空间）</td><td>中</td></tr></tbody></table><blockquote><p>本质判断：<strong>Diffusion = 质量+稳定，GAN = 速度+保真，VAE = 表征+可控。</strong> 现代系统常组合：VAE 做 tokenizer + Diffusion 做生成（Latent Diffusion）。</p></blockquote><hr><h2 id="四、高频追问" tabindex="-1">四、高频追问 <a class="header-anchor" href="#四、高频追问" aria-label="Permalink to &quot;四、高频追问&quot;">​</a></h2><p><strong>Q1：mode collapse 是什么？怎么缓解？</strong></p><blockquote><p>G 只生成少数几种样本骗过 D。缓解：minibatch discrimination、Wasserstein GAN（WGAN，用 Earth-Mover 距离 + Lipschitz 约束）、谱归一化、多尺度。</p></blockquote><p><strong>Q2：VAE 的 KL 项有什么用？</strong></p><blockquote><p>逼隐空间规整到先验（标准正态），保证能从随机 z 采样生成；否则隐空间扭曲、无法插值生成。</p></blockquote><p><strong>Q3：为什么 VQGAN 用离散 codebook？</strong></p><blockquote><p>离散表征更易被自回归/扩散模型建模，且保留语义结构，是文生图「图像 tokenizer」的常见方案。</p></blockquote><hr><p>➡️ 下一步：<a href="./03-多模态与语音生成">03-多模态与语音生成</a></p>',33)])])}const g=o(d,[["render",n]]);export{A as __pageData,g as default};
